frag:
#version 300 es
precision highp float;

uniform vec2  uResolution;
uniform vec4  uGlassBounds;        // panel rect (x, y, w, h) in UV space
uniform float uTime;               // seconds
uniform float uRefractionStrength; // squircle displacement magnitude (press-driven)
uniform float uChromatic;          // thin-rim R/B fringe strength
uniform float uCausticIntensity;   // DEMOTED ≤ 0.08
uniform float uMetalStrength;      // anisotropic-specular dominance over the field
uniform float uFoldFreq;           // drapery fold frequency
uniform vec2  uLightDir;           // virtual light direction (UV)
uniform float uPlateAlpha;         // warm-cream-plate dimming (K3); 0 = pure structured
uniform float uPlateAlphaMax;      // K12 valve ceiling: the plate firmness under a bright ridge
uniform float uValveKnee;          // K12 valve knee: structured-luma above which the plate firms
uniform float uMetalFidelity;      // per-surface dial: 1 = full drapery (chrome), low = content sheen
uniform float uA11yOpaque;         // K8: 1 → firm to the opaque CSS plate floor
uniform vec3  uPlateColor;         // pre-tinted warm-cream plate (CPU-cached, K4)
uniform vec3  uWarmBase;           // metal base hue (linear-ish warm)
uniform vec3  uWarmRidge;          // metal specular tip (warm-white)
uniform sampler2D uField;          // the shell-field texture (the ONE shared FBO)

out vec4 fragColor;

#define PI 3.14159265358979

// ── host noise basis ──────────────────────────────────────────────────────────
float hash21(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}
float vnoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash21(i),            hash21(i + vec2(1.0, 0.0)), u.x),
             mix(hash21(i + vec2(0.0, 1.0)), hash21(i + vec2(1.0, 1.0)), u.x), u.y);
}

const mat2 FBM_ROT = mat2(0.8, 0.6, -0.6, 0.8);
float fbm(vec2 p) {
  float v = 0.0;
  float a = 0.5;
  for (int i = 0; i < 5; i++) { v += a * vnoise(p); p = FBM_ROT * p * 2.0; a *= 0.5; }
  return v;
}


float srgbToLinearCh(float c) {
    return c <= 0.04045 ? c / 12.92 : pow((c + 0.055) / 1.055, 2.4);
}
vec3 srgbToLinear(vec3 c) {
    return vec3(srgbToLinearCh(c.r), srgbToLinearCh(c.g), srgbToLinearCh(c.b));
}

float linearToSrgbCh(float c) {
    return c <= 0.0031308 ? c * 12.92 : 1.055 * pow(c, 1.0 / 2.4) - 0.055;
}
vec3 linearToSrgb(vec3 c) {
    return vec3(linearToSrgbCh(c.r), linearToSrgbCh(c.g), linearToSrgbCh(c.b));
}

const float CURL_EPS = 0.012;

// Scalar fbm potential psi — the host's noise basis, wrapped so the curl operator is
// basis-agnostic. A host carrying its own fbm defines this as: return fbm(p);
float potentialFBM(vec2 p);

// ∇×ψ in 2D — the divergence-free flow direction. Central finite differences of the
// scalar potential give the partials; the cross-pairing (∂y, −∂x) is the 2D curl.
vec2 curlFBM(vec2 p) {
  float dx = potentialFBM(p + vec2(CURL_EPS, 0.0)) - potentialFBM(p - vec2(CURL_EPS, 0.0));
  float dy = potentialFBM(p + vec2(0.0, CURL_EPS)) - potentialFBM(p - vec2(0.0, CURL_EPS));
  // ψ-gradient is (dx, dy)/(2·eps); the curl rotates it 90°: (∂ψ/∂y, −∂ψ/∂x).
  vec2 g = vec2(dx, dy) / (2.0 * CURL_EPS);
  return vec2(g.y, -g.x);
}

// The scalar potential ψ for curlFBM — this host's fbm (the splice forward-declares it).
float potentialFBM(vec2 p) { return fbm(p); }


// Apple soft-superellipse bevel height: 0 at rim (x=0), 1 at center (x=1).
float squircleBevel(float x) {
  float xc = clamp(x, 0.0, 1.0);
  float k = 1.0 - xc;
  return pow(max(1.0 - k * k * k * k, 0.0), 0.25);
}

// Bounded rim-concentrated displacement weight: 1 at the rim, 0 in the interior.
float squircleRimWeight(float x) {
  return 1.0 - squircleBevel(x);
}

// Clamped analytic slope d(bevel)/dx — the Snell-at-the-bevel gradient, high at the
// rim, 0 in the flat interior. Clamped so the rim singularity stays bounded.
float squircleSlope(float x) {
  float xc = clamp(x, 0.0, 1.0);
  float k = 1.0 - xc;
  float k4 = k * k * k * k;
  float denom = pow(max(1.0 - k4, 1e-4), 0.75);
  return clamp((k * k * k) / denom, 0.0, 6.0);
}

void main() {
  vec2 uv = gl_FragCoord.xy / uResolution;
  vec2 px = 1.0 / uResolution;

  vec2 gmin = uGlassBounds.xy;
  vec2 gmax = uGlassBounds.xy + uGlassBounds.zw;

  // Outside the panel → field passthrough (the per-route suppression / Tier-0 read).
  if (uv.x < gmin.x || uv.x > gmax.x || uv.y < gmin.y || uv.y > gmax.y) {
    fragColor = texture(uField, uv);
    return;
  }

  vec2  luv  = (uv - gmin) / uGlassBounds.zw;        // [0,1] within the panel
  vec2  edgeD = min(luv, 1.0 - luv) * 2.0;           // 0 at edge, 1 at center per axis
  float edge  = min(edgeD.x, edgeD.y);               // 0 rim → 1 interior
  vec2  inward = normalize((vec2(0.5) - luv) + 1e-5);

  // ── squircle bevel displacement: rim-concentrated magnification (the lens) ──
  float rimW = squircleRimWeight(edge);
  vec2  disp = inward * rimW * uRefractionStrength * 0.045;

  // ── the displaced field sample + thin-rim chromatic fringe (R/B split at rim) ──
  float rim = 1.0 - smoothstep(0.0, 0.16, edge);
  vec2  ca  = inward * rim * uChromatic * 0.0045;
  vec3  lensed;
  lensed.r = texture(uField, uv + disp + ca).r;
  lensed.g = texture(uField, uv + disp).g;
  lensed.b = texture(uField, uv + disp - ca).b;

  // ≤9-tap soft (3×3 box) — SHARP ridges need a tiny kernel; a heavy blur kills the read.
  vec3 soft = vec3(0.0);
  for (int x = -1; x <= 1; x++) {
    for (int y = -1; y <= 1; y++) {
      soft += texture(uField, uv + disp + vec2(float(x), float(y)) * px * 2.0).rgb;
    }
  }
  soft /= 9.0;
  lensed = mix(lensed, soft, 0.35);

  // ── the anisotropic-specular METAL drapery (self-generated structured light) ──
  // Domain-warped PARALLEL folds: long near-vertical drapery the curl flow MEANDERS
  // (the liquid-metal reference is vertical folds that flow, NOT iso-contour marble).
  // A primary vertical stripe coordinate warped by the divergence-free curl field →
  // long folds that wave and braid like flowing metal. The displacement is anisotropic
  // by construction: the fold gradient is dominantly cross-flow (X), the streak runs Y.
  vec2  fp   = luv * vec2(1.6, 2.4) + vec2(uTime * 0.015, uTime * 0.01);
  float psi  = potentialFBM(fp);                      // BOUNDED [0,1] meander
  vec2  flow = curlFBM(fp);                           // the divergence-free flow (direction)
  // primary fold axis = X (vertical folds); the bounded potential gently MEANDERS them
  // (long, bold drapes that wave — never the raw-curl-dominated marble). coord const = a fold.
  float coord = luv.x * uFoldFreq + (psi - 0.5) * 2.2;
  float tri   = abs(fract(coord) - 0.5) * 2.0;        // 0 at ridge line, 1 in valley
  float shade = 1.0 - tri;                            // 0 valley → 1 ridge face
  // BROAD satin specular (the reference is soft draped foil, not thin lightning); the
  // smooth bold shading is the dominant read, a sharper glint sits on the brightest part.
  float ridge = pow(shade, 3.5);

  // The fold normal (mostly X, tilted by the flow); it catches the light anisotropically.
  vec2  foldN  = normalize(vec2(uFoldFreq, flow.y * 1.2));
  float lightAlign = abs(dot(foldN, normalize(uLightDir)));
  // LOW-freq runs along the drape (a few long bright segments per fold, never straw).
  vec2  fdir   = normalize(vec2(-foldN.y, foldN.x));
  float runPhase = dot(luv, fdir) * 1.7 + psi * 1.5;
  float run = 0.55 + 0.45 * vnoise(vec2(runPhase, coord * 0.3));
  float spec = ridge * (0.45 + 0.55 * lightAlign) * run;

  // Warm LUMINANCE ramp (K2): bronze valley (NOT black) → bright-gold fold. Hue HELD.
  // The BOLD smooth satin shading dominates; the broad specular glint sits on top.
  float satin    = smoothstep(0.0, 1.0, shade);
  float lumaRamp = 0.24 + 0.76 * satin;
  vec3  metalFull = uWarmBase * lumaRamp + uWarmRidge * spec * 0.85;
  // Per-surface FIDELITY dial (K12 option B): a content-bearing surface dims the drapery
  // to a legible bronze SHEEN; a chrome/nav surface (no body text) keeps the full bright
  // drapery. ONE dial, the architectural answer (Apple HIG: glass on nav, not content).
  vec3  metal = metalFull * mix(0.5, 1.0, uMetalFidelity);

  // Caustic DEMOTED ≤ 0.08 — a faint isotropic shimmer, never dominant (no swimming-pool).
  metal += vec3(vnoise(luv * 8.0 + uTime * 0.1) * uCausticIntensity);

  // ── compose: metal drapery over the lensed field ──
  vec3 structured = mix(lensed, metal, uMetalStrength);

  // ── the warm-cream-plate dimming (K3) + the ridge-local VALVE (K12) + a11y floor (K8) ──
  float structLuma = dot(structured, vec3(0.2126, 0.7152, 0.0722));
  // The valve firms the plate WHERE the structured luma exceeds the knee (the bright ridge
  // core under text) — the dim valley stays translucent, so the metal still reads, but the
  // peak-bright ridge firms toward the opaque plate so light text clears AA over it.
  float valve  = smoothstep(uValveKnee, 1.0, structLuma);
  float plateA = max(uPlateAlpha, uA11yOpaque);      // K8: opaque firms the plate to solid
  plateA       = mix(plateA, max(plateA, uPlateAlphaMax), valve);
  vec3  outc   = mix(structured, uPlateColor, plateA);

  fragColor = vec4(outc, 1.0);
}

vert:
#version 300 es
void main() {
  vec2 p = vec2(float((gl_VertexID << 1) & 2), float(gl_VertexID & 2));
  gl_Position = vec4(p * 2.0 - 1.0, 0.0, 1.0);
}
